/* Content, persistence, motion and audio are separate; this file coordinates routes and page events. */
(()=>{
 const $=s=>document.querySelector(s);
 let activeRoute='',filter='全部',query='',lastDialogTrigger;
 const names={home:'首页',journal:'构建日志',projects:'作品实验室',about:'个人档案',contact:'留言终端',gallery:'生活相册',post:'日志详情'};
 function route(){const parts=(location.hash.replace(/^#\/?/,'')||'home').split('/');if(parts[0]==='profile')parts[0]='about';return parts;}
 function closeDialogs(){Night.gallery.close();Night.lab.close();Night.runner.close();document.querySelectorAll('dialog[open]:not(#entry-gate)').forEach(d=>d.close());}
 async function openDialog(dialog){lastDialogTrigger=document.activeElement;await Night.motion.openDialog(dialog);}
 function updateFavorites(){const ids=Night.favoriteIds();document.querySelectorAll('[data-save]').forEach(b=>{const saved=ids.includes(b.dataset.save);b.setAttribute('aria-pressed',String(saved));b.textContent=saved?'★ 已收藏':'☆ 收藏';});}
 function toggleSave(id){const current=Night.favoriteIds(),saved=current.includes(id);if(!Night.store.write('favorites',saved?current.filter(v=>v!==id):[...current,id])){Night.toast('收藏未保存：浏览器存储不可用');return;}updateFavorites();if(activeRoute==='journal'){renderPosts();const replacement=document.querySelector('[data-save="'+id+'"]');if(replacement)replacement.focus({preventScroll:true});else document.querySelector('[data-filter="收藏"]').focus({preventScroll:true});}Night.toast(saved?'已取消收藏':'已加入当前浏览器的收藏');}
 function renderPosts(){const list=Night.posts.filter(p=>(filter==='全部'||(filter==='收藏'?Night.favoriteIds().includes(p.id):p.category===filter))&&[p.title,p.summary,p.category].join(' ').toLowerCase().includes(query.toLowerCase()));$('#posts').innerHTML=list.map(p=>Night.views.card(p,Night.posts.indexOf(p))).join('');$('#empty').hidden=!!list.length;$('#result-count').textContent=`检索完成 / ${list.length} 条信号`;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('selected',b.dataset.filter===filter);b.setAttribute('aria-pressed',String(b.dataset.filter===filter));});}
 function resetSearch(){filter='全部';query='';$('#search').value='';renderPosts();$('#search').focus();}
 async function renderRoute(){const [page,id]=route();closeDialogs();await Night.motion.transition(names[page]?`接入 / ${names[page]}`:'SIGNAL NOT FOUND',()=>{activeRoute=page;const main=$('#main-content');Night.pages.dispose();main.classList.remove('focus-reading');main.innerHTML=page==='post'?Night.views.article(id):Object.hasOwn(Night.views,page)&&names[page]?Night.views[page]():Night.views.missing();document.title=(page==='post'?(Night.posts.find(p=>p.id===id)?.title||'信号失联'):names[page]||'信号失联')+' / NIGHT.LOG';document.querySelectorAll('.header nav a').forEach(a=>{const selected=a.hash===`#/${page==='post'?'journal':page}`;a.classList.toggle('active',selected);if(selected)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});window.scrollTo({top:0,behavior:'instant'});main.classList.remove('view-enter');void main.offsetWidth;main.classList.add('view-enter');main.focus({preventScroll:true});updateFavorites();if(page==='home')updateClock();if(page==='journal'){filter='全部';query='';$('#search').addEventListener('input',e=>{query=e.target.value.trim();renderPosts();});renderPosts();}if(page==='contact')bindContact();Night.pages.mount(page);});}
 function renderMessages(){const list=Night.messages(),container=$('#messages');container.replaceChildren();if(!list.length){const empty=document.createElement('p');empty.className='empty-message';empty.textContent='还没有本地留言。写下第一条反馈吧。';container.append(empty);}else list.slice().reverse().forEach(m=>{const item=document.createElement('article');item.className='message-item';const title=document.createElement('h3'),meta=document.createElement('p'),text=document.createElement('p');title.textContent=m.name;meta.className='message-meta';meta.textContent=m.topic+' / '+new Date(m.date).toLocaleString('zh-CN');text.className='message-text';text.textContent=m.text;item.append(title,meta,text);container.append(item);});$('#export-messages').disabled=!list.length;$('#clear-messages').disabled=!list.length;}
 function bindContact(){const form=$('#message-form'),name=$('#visitor-name'),topic=$('#message-topic'),text=$('#message-text'),status=$('#form-status');const draft=Night.store.read('draft',{});if(draft&&typeof draft==='object'){name.value=typeof draft.name==='string'?draft.name.slice(0,20):'';topic.value=['设计反馈','功能建议','学习交流'].includes(draft.topic)?draft.topic:'';text.value=typeof draft.text==='string'?draft.text.slice(0,500):'';}
  const values=()=>({name:name.value.trim(),topic:topic.value,text:text.value.trim()});
  function validate(field){const v=values();let message='';if(field===name&&(v.name.length<2||v.name.length>20))message='请输入 2—20 个字符的昵称。';if(field===topic&&!v.topic)message='请选择一项信号主题。';if(field===text&&(v.text.length<10||v.text.length>500))message='留言内容需要 10—500 个字符。';const target=field===name?$('#name-error'):field===topic?$('#topic-error'):$('#text-error');target.textContent=message;field.setAttribute('aria-invalid',String(!!message));return !message;}
  function updateDraft(){const ok=Night.store.write('draft',{name:name.value,topic:topic.value,text:text.value});$('#character-count').textContent=text.value.length+' / 500';status.textContent=ok?'草稿已自动保存到当前浏览器。':'草稿无法保存，请勿关闭页面。';}
  [name,topic,text].forEach(field=>{field.addEventListener('input',()=>{if(field.getAttribute('aria-invalid')==='true')validate(field);updateDraft();});field.addEventListener('blur',()=>validate(field));});$('#character-count').textContent=text.value.length+' / 500';
  form.addEventListener('submit',e=>{e.preventDefault();const invalid=[name,topic,text].map(field=>({field,valid:validate(field)})).find(c=>!c.valid);if(invalid){status.textContent='保存失败：请先修正下方标出的输入。';invalid.field.focus();return;}const button=form.querySelector('[type="submit"]');button.disabled=true;const ok=Night.store.write('messages',[...Night.messages(),{...values(),date:new Date().toISOString()}].slice(-50));button.disabled=false;if(!ok){status.textContent='保存失败：浏览器存储不可用。你的输入已保留，可以复制后另行保存。';return;}const cleared=Night.store.write('draft',{});form.reset();[name,topic,text].forEach(f=>f.removeAttribute('aria-invalid'));$('#character-count').textContent='0 / 500';status.textContent=cleared?'本地保存成功。记录只在当前浏览器可见，未发送给作者。':'留言已保存，但旧草稿未能清除。';renderMessages();Night.pages.messageSaved();Night.toast('信号已保存到本地终端');});
  $('#clear-draft').addEventListener('click',()=>{if(!Night.store.write('draft',{})){status.textContent='无法清除草稿：浏览器存储不可用。';return;}form.reset();document.querySelectorAll('.field-error').forEach(p=>p.textContent='');[name,topic,text].forEach(f=>f.removeAttribute('aria-invalid'));$('#character-count').textContent='0 / 500';status.textContent='草稿已清除。';});
  $('#export-messages').addEventListener('click',()=>{const list=Night.messages();if(!list.length)return;const url=URL.createObjectURL(new Blob([JSON.stringify(list,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='NIGHT-LOG-messages.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);Night.toast('已生成本地留言 JSON 文件');});
  $('#clear-messages').addEventListener('click',()=>{const dialog=$('#reader');$('#reader-label').textContent='CONFIRM / 清空本地留言';$('#reader-content').innerHTML='<h2>清空当前浏览器的留言？</h2><p>此操作会删除本地留言记录，不影响尚未提交的草稿。需要留存时，请先导出 JSON。</p><div class="form-actions"><button class="button primary" id="confirm-clear">确认清空</button><button class="small-button" id="cancel-clear">取消，保留记录</button></div>';openDialog(dialog);$('#cancel-clear').focus();$('#cancel-clear').onclick=()=>dialog.close();$('#confirm-clear').onclick=()=>{if(!Night.store.write('messages',[])){Night.toast('清空失败：浏览器存储不可用');return;}dialog.close();renderMessages();Night.toast('本地留言记录已清空');};});renderMessages();
 }
 function showProject(id){lastDialogTrigger=document.activeElement;if(id==='piano'||id==='signal'){Night.runner.close();Night.lab.show();return;}if(id==='runner'||id==='nightlog'){Night.runner.show();return;}}
 async function openTerminal(){closeDialogs();await openDialog($('#terminal'));if($('#terminal').open)$('#command').focus();}
 document.addEventListener('click',e=>{if(e.target.closest('.skip-link')){e.preventDefault();document.getElementById("main-content").focus();document.getElementById("main-content").scrollIntoView();return;}const save=e.target.closest('[data-save]');if(save){toggleSave(save.dataset.save);return;}const fb=e.target.closest('[data-filter]');if(fb){filter=fb.dataset.filter;renderPosts();return;}if(e.target.closest('#reset-search,#empty-reset')){resetSearch();return;}const project=e.target.closest('[data-project]');if(project){showProject(project.dataset.project);return;}const scroll=e.target.closest('[data-scroll]');if(scroll){e.preventDefault();const section=document.getElementById(scroll.dataset.scroll);section?.scrollIntoView({behavior:Night.motion.level()==='full'?'smooth':'instant'});section?.focus({preventScroll:true});return;}const link=e.target.closest('a[href^="#/"]');if(link&&link.hash===location.hash){e.preventDefault();closeDialogs();window.scrollTo({top:0,behavior:Night.motion.level()==='full'?'smooth':'instant'});Night.toast('当前已在此界面');}});
 document.querySelectorAll('dialog .close').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));document.querySelectorAll('dialog').forEach(d=>{d.addEventListener('click',e=>{const r=d.getBoundingClientRect();if(e.target===d&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))d.close();});d.addEventListener('close',()=>{d.classList.remove('dialog-enter');if(lastDialogTrigger?.isConnected)lastDialogTrigger.focus({preventScroll:true});});});$('#reader').addEventListener('close',Night.lab.close);$('#reader').addEventListener('close',Night.runner.close);
 $('.terminal-trigger').addEventListener('click',openTerminal);$('#settings-trigger').addEventListener('click',()=>{Night.motion.apply();openDialog($('#settings'));});document.querySelectorAll('[name="motion"]').forEach(r=>r.addEventListener('change',()=>Night.motion.set(r.value)));
 document.addEventListener('keydown',e=>{if(e.key==='/'&&!document.documentElement.classList.contains('is-routing')&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();openTerminal();}});
 const commands={home:'home',posts:'journal',projects:'projects',about:'about',contact:'contact',photos:'gallery'};
 $('#terminal-form').addEventListener('submit',e=>{e.preventDefault();const raw=$('#command').value.trim(),cmd=raw.toLowerCase();if(!cmd)return;const out=$('#terminal-output');function line(t){const p=document.createElement('p');p.textContent=t;out.append(p);}line('visitor@night:~$ '+raw);$('#command').value='';if(commands[cmd]){$('#terminal').close();if(location.hash==='#/'+commands[cmd])renderRoute();else location.hash='#/'+commands[cmd];}else if(cmd==='exit')$('#terminal').close();else if(cmd==='clear')out.replaceChildren();else if(cmd==='date')line(new Date().toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})+' CST');else if(cmd==='help')line('home 首页 / posts 日志 / projects 作品 / about 档案 / contact 留言 / photos 相册\nsettings 动效设置 / date 时间 / clear 清屏 / exit 退出');else if(cmd==='settings'){$('#terminal').close();openDialog($('#settings'));}else line('未识别的命令。输入 help 查看帮助。');while(out.children.length>70)out.firstElementChild.remove();out.scrollTop=out.scrollHeight;});
 function updateClock(){const clock=$('#clock');if(clock)clock.textContent=new Date().toLocaleTimeString('en-GB',{timeZone:'Asia/Shanghai'});}setInterval(updateClock,1000);
 window.addEventListener('hashchange',renderRoute);renderRoute();
})();


